// A terminal on the frame's own screen: a line to type commands into and the
// frame's answers above it (docs/terminal.md). The commands are an ESP32
// serial console's (help, status, set, wifi, wifi-scan, render, event, scenes,
// scene, restart, reboot), answered through frameos.frame: the facts the frame
// page shows, its Save and its buttons. That needs the "frame" permission
// (installing the scene is the owner's yes) and the frame's settings allowed on
// its screen.
//
// The lines and the commands typed are kept with frameos.remember, so they
// outlast an interpreter that was let go. Enter runs the line (the field is a
// one-line textarea, which keeps the keyboard after Enter), ArrowUp and
// ArrowDown walk the commands typed before, and a swipe down on the lines
// scrolls back through them.

const MAX_LINES = 200
const MAX_HISTORY = 50
const PROMPT = 'frameos>'

let draft = null // the line as typed, while this interpreter lives
let walk = -1 // where in the history ArrowUp has got to
let back = 0 // rows scrolled back

const kept = (key, empty) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}

function say(entries) {
  const lines = kept('lines', []).concat(entries)
  frameos.remember('lines', lines.slice(-MAX_LINES))
  back = 0
}

// A line is { t } (an answer), { p: 1, t } (a command after the prompt) or
// { k, t } (a status line's key and value).
const out = (...texts) => texts.map((t) => ({ t: String(t) }))
const pair = (k, v) => ({ k, t: String(v) })
const LOCKED = "refused: the frame's control plane has turned settings on its screen off"

// frameos.frame, and why it refused in the console's words.
function frame(op, arg) {
  try {
    return { ok: true, value: frameos.frame(op, arg) }
  } catch (e) {
    return { ok: false, why: 'refused: ' + String((e && e.message) || e).replace(/^frameos\.frame: /, '') }
  }
}

// The line split as esp_console splits it: at spaces, a "quoted part" one
// word, a backslash taking the next character as it is.
function words(line) {
  const result = []
  let word = ''
  let started = false
  let quoted = false
  for (let i = 0; i < line.length; i++) {
    const c = line[i]
    if (c === '\\' && i + 1 < line.length) {
      word += line[++i]
      started = true
    } else if (c === '"') {
      quoted = !quoted
      started = true
    } else if (/\s/.test(c) && !quoted) {
      if (started) result.push(word)
      word = ''
      started = false
    } else {
      word += c
      started = true
    }
  }
  if (started) result.push(word)
  return result
}

const HELP = [
  ['help', 'Print the list of commands'],
  ['status', 'Show device status'],
  ['set', 'set <key> <value>: rotate, render_scale, wifi_ssid, wifi_pass'],
  ['wifi', 'wifi <ssid> [pass]: set Wi-Fi and join it'],
  ['wifi-scan', 'Scan visible Wi-Fi networks'],
  ['render', 'Render now'],
  ['event', 'event <name> [json]: render, restart or reboot'],
  ['scenes', "Show the frame's scenes"],
  ['scene', 'scene <id>: select a scene and render'],
  ['restart', 'Restart FrameOS'],
  ['reboot', 'Reboot the device'],
  ['clear', 'Clear the screen'],
]

function status(app) {
  const facts = frame('read').value
  const lines = []
  const wifi = facts && facts.wifi
  if (wifi) {
    let line = `ssid="${wifi.ssid}" state=${wifi.state}`
    if (wifi.ip) line += ` ip=${wifi.ip}`
    if (typeof wifi.rssi === 'number') line += ` rssi=${wifi.rssi}`
    lines.push(pair('wifi', line))
  }
  if (facts && facts.managedBy) lines.push(pair('managed_by', facts.managedBy))
  const f = app.frame
  lines.push(pair('panel', `${f.width * (f.scale || 1)}x${f.height * (f.scale || 1)}`))
  lines.push(pair('rotate', facts ? facts.rotate : f.rotate))
  if (facts) lines.push(pair('render_scale', facts.renderScale + (facts.renderScale ? '' : ' (automatic)')))
  lines.push(pair('frame_page', facts ? 'offered' : 'off'))
  lines.push(pair('time_zone', f.timeZone || '(UTC)'))
  lines.push(pair('debug', f.debug ? 1 : 0))
  const battery = facts && facts.battery ? facts.battery.percent : f.batteryPercent
  lines.push(pair('battery', typeof battery === 'number' ? battery + '%' : 'not configured'))
  if (Array.isArray(f.scenes)) lines.push(pair('scenes', f.scenes.length))
  if (facts && facts.version) lines.push(pair('version', facts.version))
  if (facts && facts.note) lines.push(pair('note', facts.note))
  return lines
}

function apply(changes, done) {
  const facts = frame('read')
  if (!facts.ok) return out(facts.why)
  if (!facts.value) return out(LOCKED)
  if (('wifiSsid' in changes || 'wifiPassword' in changes) && !facts.value.wifi) {
    return out('this frame has no Wi-Fi to set from its screen')
  }
  const r = frame('apply', changes)
  return out(r.ok ? done : r.why)
}

function set(args) {
  const [, key, ...rest] = args
  const value = rest.join(' ')
  if (!key || !value) return out('usage: set <rotate|render_scale|wifi_ssid|wifi_pass> <value...>')
  if (key === 'rotate') {
    const rotate = Number(value)
    if (![0, 90, 180, 270].includes(rotate)) return out('bad rotate value, want 0, 90, 180 or 270')
    return apply({ rotate }, 'ok: rotate set (the frame restarts for it)')
  }
  if (key === 'render_scale') {
    const scale = Number(value)
    if (!(scale >= 0 && scale <= 4)) return out('render_scale: 0 (automatic) to 4')
    return apply({ renderScale: scale }, 'ok: render_scale set')
  }
  if (key === 'wifi_ssid') return apply({ wifiSsid: value }, 'ok: wifi_ssid set')
  if (key === 'wifi_pass') return apply({ wifiPassword: value }, 'ok: wifi_pass set')
  return out(`set ${key}: not from this frame's screen; its control plane sets it`)
}

function action(name, done) {
  const r = frame('action', name)
  return out(r.ok ? done : r.why)
}

function scenes(app) {
  const list = app.frame.scenes
  if (!Array.isArray(list)) return out('this frame does not list its scenes here')
  return [
    ...out(`scenes: ${list.length} loaded`),
    ...list.map((s) => ({ t: `${s.id === app.frame.sceneId ? '* ' : '  '}${s.id}  ${s.name || ''}` })),
  ]
}

// One command line, as fos_console.c's run_console_line runs one.
function run(app, line) {
  const args = words(line)
  if (!args.length) return []
  const name = args[0]
  switch (name) {
    case 'help':
      return HELP.map(([k, t]) => pair(k, t))
    case 'status':
      return status(app)
    case 'set':
      return set(args)
    case 'wifi':
      if (args.length < 2) return out('usage: wifi <ssid> [password]')
      return apply({ wifiSsid: args[1], wifiPassword: args[2] || '' }, `wifi credentials saved, joining ${args[1]}`)
    case 'wifi-scan': {
      const read = frame('read')
      const facts = read.value
      if (!read.ok) return out(read.why)
      if (!facts) return out(LOCKED)
      if (!facts.wifi) return out('wifi-scan: this frame has no Wi-Fi to scan with here')
      const r = frame('action', 'scan')
      if (!r.ok) return out(r.why)
      frameos.remember('pending', 'scan')
      return out('scanning...')
    }
    case 'render':
      return action('render', 'render triggered')
    case 'event': {
      if (args.length < 2) return out('usage: event <name> [json payload]', '  e.g. event render {}')
      if (!['render', 'restart', 'reboot'].includes(args[1])) return out('event refused: not one the console may send')
      return action(args[1], `sent ${args[1]} {}`)
    }
    case 'scenes':
      return scenes(app)
    case 'scene': {
      if (args.length < 2) return [...out('usage: scene <scene-id>'), ...scenes(app)]
      const list = app.frame.scenes
      if (Array.isArray(list) && !list.some((s) => s.id === args[1])) {
        return out(`scene select failed: no scene ${args[1]} on this frame`)
      }
      frameos.dispatch('setCurrentScene', { sceneId: args[1] })
      return out(`scene queued: ${args[1]}`)
    }
    case 'restart': {
      const facts = frame('read').value
      if (facts && Array.isArray(facts.actions) && facts.actions.includes('restart')) {
        return action('restart', 'restarting FrameOS...')
      }
      return action('reboot', 'rebooting...')
    }
    case 'reboot':
      return action('reboot', 'rebooting...')
    case 'clear':
      frameos.remember('lines', [])
      return null
  }
  return out(`unknown command: ${line}`)
}

function enter(app, line) {
  const text = line.trim()
  say([{ p: 1, t: text }])
  walk = -1
  if (text) {
    const history = kept('history', []).filter((h) => h !== text)
    history.push(text)
    frameos.remember('history', history.slice(-MAX_HISTORY))
    const answer = run(app, text)
    if (answer) say(answer)
  }
}

// What a scan brought back since the last render.
function collect() {
  const pending = frameos.recall('pending')
  if (pending === 'scan') {
    const facts = frame('read').value
    const wifi = facts && facts.wifi
    if (!wifi || !wifi.scanning) {
      frameos.remember('pending', null)
      const networks = (wifi && wifi.networks) || []
      const count = `${networks.length} network${networks.length === 1 ? '' : 's'}:`
      say(networks.length ? [...out(count), ...networks.map((n) => ({ t: '  ' + n }))] : out('no networks found'))
    } else {
      frameos.setNextSleep(1)
    }
  }
  return frameos.recall('pending')
}

function walkHistory(step) {
  const history = kept('history', [])
  if (!history.length || (walk < 0 && step > 0)) return
  walk = walk < 0 ? history.length - 1 : Math.max(0, walk + step)
  if (walk >= history.length) walk = -1
  draft = walk < 0 ? '' : history[walk]
  frameos.remember('draft', draft)
}

function getInRoom(app, context) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const room = roundRoom(app, context)
  const width = room ? room.side : (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = room ? room.side : (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // Letters keep their size wherever it shows: a bigger window shows more lines.
  // It is the size of a desktop's own text, by the frame and not by the window,
  // smaller in proportion under 480. The frame's render scale makes it larger
  // (app.frame's size is already over it; automatic is 2 on a 4K screen or a 10"
  // e-paper). Grown with the frame from 480, a browser the size of a laptop's
  // screen drew it at 1.75x.
  // A big e-paper at render scale 1 (a 13.3" one) is read from further away:
  // twice as large there, as its other scenes are.
  const shortSide = Math.min(app.frame.width, app.frame.height)
  const zoom = shortSide >= 960 && paper ? 2 : shortSide >= 480 ? 1 : Math.max(0.75, shortSide / 480)
  const size = Math.round(15 * zoom)
  const rowH = Math.round(size * 1.4)
  const pad = Math.round(8 * zoom)
  const gap = Math.round(size * 0.35)

  if (draft === null) draft = kept('draft', '')
  const pending = collect()

  // Rows as they will show: a line cut where a row ends, at a space where
  // there is one in the row, as the frame's one face leaves room for
  // (letters are about 0.6 of the size wide at most).
  // A key and its value: the value in a column of its own, its rows wrapped
  // under it, so a wrapped value never reads as a key.
  const keyW = Math.round(size * 6.6)
  const cols = Math.max(8, Math.floor((width - pad * 2) / (size * 0.6)))
  const valueCols = Math.max(8, Math.floor((width - pad * 2 - keyW - gap) / (size * 0.6)))
  const rowsOf = (entries) => {
    const rows = []
    for (const entry of entries) {
      if (entry.k && keyW + gap + size * 0.6 * 8 <= width - pad * 2) {
        // The value alone wraps; the key is drawn on the first row.
        const text = entry.t
        let at = 0
        do {
          let end = Math.min(text.length, at + valueCols)
          if (end < text.length) {
            const space = text.lastIndexOf(' ', end)
            if (space > at) end = space
          }
          rows.push({ k: entry.k, v: text.slice(at, end), first: at === 0 })
          at = end
          while (at > 0 && text[at] === ' ') at++
        } while (at < text.length)
        continue
      }
      const text = entry.p ? PROMPT + ' ' + entry.t : entry.k ? entry.k + ': ' + entry.t : entry.t
      let at = 0
      do {
        let end = Math.min(text.length, at + cols)
        if (end < text.length) {
          const space = text.lastIndexOf(' ', end)
          if (space > at) end = space
        }
        rows.push({ ...entry, t: text.slice(at, end), first: at === 0 })
        at = end
        while (at > 0 && text[at] === ' ') at++
      } while (at < text.length)
    }
    return rows
  }
  const fit = Math.max(1, Math.floor((height - pad * 2) / rowH)) - 1
  const line = `h-[${rowH}px] leading-[${rowH}px]`
  // A screen with nothing on it yet says what it is and what to type, the
  // commands under it (only their names where they would not all show),
  // until the first command, and again after a clear.
  const lines = kept('lines', [])
  let rows = rowsOf(lines)
  if (!lines.length) {
    const title = out("FrameOS terminal: the frame's console.")
    rows = rowsOf([...title, ...out('Type a command and press Enter:'), ...HELP.map(([k, t]) => pair(k, t))])
    if (rows.length > fit) rows = rowsOf([...title, ...out('Type help and press Enter. The commands:', HELP.map(([k]) => k).join(' '))])
  }
  back = Math.max(0, Math.min(back, rows.length - fit))
  const shown = rows.slice(Math.max(0, rows.length - fit - back), rows.length - back)

  const fg = ink ? 'text-black' : 'text-[#d0d0d0]'
  const green = ink ? 'text-black font-bold' : 'text-[#4ade80]'
  const dim = ink ? 'text-black' : 'text-[#8b93a7]'
  return (
    // From the top, as a terminal starts: the lines, and the prompt under the
    // last of them; once they fill the screen the oldest go off the top.
    <div
      className={`flex flex-col w-full h-full p-[${pad}px] ${ink ? 'bg-white' : 'bg-black'} ${fg} text-[${size}px]`}
      onSwipe={(e) => {
        back += e.direction === 'down' ? fit - 1 : e.direction === 'up' ? 1 - fit : 0
      }}
    >
      {shown.map((row) => (
        <div className={`flex ${line} shrink-0 items-center gap-[${gap}px] whitespace-nowrap overflow-hidden`}>
          {row.v !== undefined ? (
            <span className={`${dim} shrink-0 w-[${keyW}px]`}>{row.first ? row.k + ':' : ''}</span>
          ) : row.first && row.p ? (
            <span className={green}>{PROMPT}</span>
          ) : row.first && row.k ? (
            <span className={`${dim} shrink-0 min-w-[${keyW}px]`}>{row.k + ':'}</span>
          ) : null}
          <span>{row.v !== undefined ? row.v : !row.first ? row.t : row.p ? row.t.slice(PROMPT.length) : row.k ? row.t.slice(row.k.length + 1) : row.t}</span>
        </div>
      ))}
      <div className={`flex ${line} shrink-0 items-center gap-[${gap}px]`}>
        <span className={green}>{PROMPT}</span>
        <textarea
          className={`flex-1 ${line} ${fg} ${ink ? 'focus:bg-white' : 'focus:bg-[#111111]'}`}
          value={draft}
          placeholder={ink ? '' : 'help'}
          onChange={(e) => {
            const text = String(e.target.value)
            const at = text.indexOf('\n')
            if (at < 0) {
              draft = text
            } else {
              enter(app, text.slice(0, at))
              draft = text.slice(at + 1).replace(/\n/g, '')
            }
            frameos.remember('draft', draft)
          }}
          onKeyDown={(e) => {
            if (e.key === 'ArrowUp') walkHistory(-1)
            else if (e.key === 'ArrowDown') walkHistory(1)
            else if (e.key === 'PageUp') back += fit - 1
            else if (e.key === 'PageDown') back -= fit - 1
          }}
        />
      </div>
      <div className="flex-1" />
    </div>
  )
}

// A round panel (app.frame.round) shows only the circle inside its square.
// Drawn on the whole panel, the app lays out in the square inside that circle
// and is drawn there; in a window or a layout's hole its room is its own.
function roundRoom(app, context) {
  if (app.frame.round !== true) return null
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const panelWidth = (turned ? app.frame.height : app.frame.width) || 0
  const panelHeight = (turned ? app.frame.width : app.frame.height) || 0
  if (context && context.imageWidth && (Math.abs(context.imageWidth - panelWidth) > 2 || Math.abs(context.imageHeight - panelHeight) > 2)) {
    return null
  }
  const side = Math.floor((Math.min(panelWidth, panelHeight) / 2 - 12) * Math.SQRT2)
  return {
    width: panelWidth,
    height: panelHeight,
    side,
    x: Math.floor((panelWidth - side) / 2),
    y: Math.floor((panelHeight - side) / 2),
  }
}

export function get(app, context) {
  const ui = getInRoom(app, context)
  const room = roundRoom(app, context)
  if (!room || !ui || typeof ui !== 'object') return ui
  return (
    <div className={`relative w-[${room.width}px] h-[${room.height}px]`}>
      <div className={`absolute left-[${room.x}px] top-[${room.y}px] w-[${room.side}px] h-[${room.side}px]`}>{ui}</div>
    </div>
  )
}

