import { get } from './app'

const FACTS = {
  wifi: { state: 'connected', ssid: 'Home', ip: '10.0.0.5', rssi: -52, networks: [], scanning: false, password: true },
  rotate: 0,
  renderScale: 0,
  actions: ['restart'],
  version: '2026.11.8',
}

// Every string in the tree, in order: the lines and the prompt.
function texts(node: any, into: string[] = []): string[] {
  if (node === null || node === undefined || node === false) return into
  if (typeof node === 'string' || typeof node === 'number') into.push(String(node))
  else if (Array.isArray(node)) node.forEach((child) => texts(child, into))
  else if (node.props) texts(node.props.children, into)
  return into
}

function find(node: any, test: (n: any) => boolean): any {
  if (!node || typeof node !== 'object') return null
  if (Array.isArray(node)) {
    for (const child of node) {
      const hit = find(child, test)
      if (hit) return hit
    }
    return null
  }
  if (test(node)) return node
  return node.props ? find(node.props.children, test) : null
}

const screen = (app: any) => texts(get(app, makeContext())).join(' ')
const field = (app: any) => find(get(app, makeContext()), (n) => n.type === 'textarea')

// Types a line and Enter, as the keyboard on the screen does into the field.
function type(app: any, line: string): string {
  field(app).props.onChange({ value: line + '\n', target: { value: line + '\n' } })
  return screen(app)
}

describe('the terminal', () => {
  it('lists its commands', () => {
    const app = makeApp()
    mock.frame(() => FACTS)
    const shown = type(app, 'help')
    expect(shown).toContain('frameos>')
    expect(shown).toContain('wifi-scan')
    expect(shown).toContain('Reboot the device')
  })

  it('shows the facts the frame page shows', () => {
    const app = makeApp({ frame: { batteryPercent: 80 } })
    mock.frame((op: string) => (op === 'read' ? FACTS : true))
    const shown = type(app, 'status')
    expect(shown).toContain('ssid="Home" state=connected ip=10.0.0.5 rssi=-52')
    expect(shown).toContain('offered')
    expect(shown).toContain('2026.11.8')
  })

  it('sets the rotation through the page and checks it first', () => {
    const app = makeApp()
    const frame = mock.frame((op: string) => (op === 'read' ? FACTS : true))
    expect(type(app, 'set rotate 45')).toContain('bad rotate value')
    expect(frame.calls.some((call: any[]) => call[0] === 'apply')).toBe(false)
    expect(type(app, 'set rotate 90')).toContain('ok: rotate set')
    expect(frame).toHaveBeenCalledWith('apply', { rotate: 90 })
    expect(type(app, 'set api_key x')).toContain('not from this frame')
  })

  it('says why when the frame refuses', () => {
    const app = makeApp()
    mock.frame(() => {
      throw new Error("frameos.frame: settings on the frame's screen are off")
    })
    expect(type(app, 'reboot')).toContain("refused: settings on the frame's screen are off")
  })

  it('restarts FrameOS where the host can, and reboots elsewhere', () => {
    const app = makeApp()
    const frame = mock.frame((op: string) => (op === 'read' ? { ...FACTS, actions: [] } : true))
    expect(type(app, 'restart')).toContain('rebooting...')
    expect(frame).toHaveBeenCalledWith('action', 'reboot')
  })

  it('walks back through the commands typed', () => {
    const app = makeApp()
    mock.frame(() => FACTS)
    type(app, 'help')
    type(app, 'render')
    field(app).props.onKeyDown({ key: 'ArrowUp' })
    expect(field(app).props.value).toBe('render')
    field(app).props.onKeyDown({ key: 'ArrowUp' })
    expect(field(app).props.value).toBe('help')
    field(app).props.onKeyDown({ key: 'ArrowDown' })
    expect(field(app).props.value).toBe('render')
  })

  it('switches scenes by id', () => {
    const app = makeApp({ frame: { scenes: [{ id: 'clock', name: 'Clock' }], sceneId: 'terminal-app' } })
    mock.frame(() => FACTS)
    const dispatch = mock.dispatch()
    expect(type(app, 'scenes')).toContain('Clock')
    expect(type(app, 'scene nope')).toContain('no scene nope')
    expect(type(app, 'scene clock')).toContain('scene queued: clock')
    expect(dispatch).toHaveBeenCalledWith('setCurrentScene', { sceneId: 'clock' })
  })

  it('lists the networks once a scan is back', () => {
    const app = makeApp()
    let scanning = true
    mock.frame((op: string) =>
      op === 'read' ? { ...FACTS, wifi: { ...FACTS.wifi, scanning, networks: ['Home', 'Cafe'] } } : true
    )
    expect(type(app, 'wifi-scan')).toContain('scanning...')
    expect(app.nextSleep).toBe(1)
    scanning = false
    expect(screen(app)).toContain('2 networks:')
  })

  it('says which lines it does not know', () => {
    const app = makeApp()
    mock.frame(() => FACTS)
    expect(type(app, 'heapinfo')).toContain('unknown command: heapinfo')
  })
})
